\\nsecond line\\t\"\n+    val notExecuted = NotExecuted(reason)\n+    val unknown = Unknown(reason)\n+    assert(notExecuted.reason == reason)\n+    assert(unknown.reason == reason)\n+    assert(notExecuted.render == s\"NotExecuted: $reason\")\n+    assert(unknown.render == s\"Unknown: $reason\")\n+  }\n+}\n"},"receipts":[{"schema_version":"sm-workflow.native-sbt-validation-receipt.v2","identity":"sample-compile","sbt":{"kind":"compile","outcome":"succeeded"},"process":{"termination":{"kind":"exited","exit_code":0},"stdout":{"content_base64":"","byte_count":754,"truncated":false},"stderr":{"content_base64":"","byte_count":0,"truncated":false},"artifacts":[],"elapsed_millis":4118,"safe_program_identity":"sm-workflow-repository-validation-1"}},{"schema_version":"sm-workflow.native-sbt-validation-receipt.v2","identity":"sample-focused","sbt":{"kind":"test-only","outcome":"succeeded","selection":{"test_classes":["example.ExecutionLabelSpec"],"completed_suites":1,"tests_run":5}},"process":{"termination":{"kind":"exited","exit_code":0},"stdout":{"content_base64":"","byte_count":1308,"truncated":false},"stderr":{"content_base64":"","byte_count":0,"truncated":false},"artifacts":[],"elapsed_millis":3068,"safe_program_identity":"sm-workflow-repository-validation-2"}}],"automatic_count":0,"ordinary_count":0,"repair_control":{"policy":"sm-workflow.repair-trend.v1","selected_limit":10,"observations":[]},"findings":[],"unresolved_questions":[],"condition_report":[{"identity":"distinct-truthful-statuses","satisfied":true,"detail":"src/main/scala/example/ExecutionLabel.scala defines four distinct sealed variants and renders each status with its supplied details. Its runnable main prints invented examples without observing or verifying a process."},{"identity":"reject-invalid-observations","satisfied":true,"detail":"Constructors reject each nonpositive Passed count, Failed(0), and null or whitespace-only reasons. Both reason-bearing variants preserve supplied meaningful text exactly